            <h2>Indeed workflow</h2>
            <ol>
            <li>Digital PDF — try select text; scan needs <a href="/pdf/ocrpdf">OCR PDF</a> first</li>
            <li><a href="/pdf/pdftotext">PDF to Text</a> — download .txt</li>
            <li>Paste quote into employer reply or internal screening doc — link original PDF résumé on Indeed</li>
            <li>Keep PDF attached when tables or signatures matter — text paste is for quotes only</li>
            </ol>
            <h2>Attachment size</h2>
            <p>Separate step from text extract — <a href="/guides/compress-pdf-for-indeed">compress guide</a> if Indeed rejects large PDF.</p>
            <h2>Troubleshooting</h2>
