            <h2>Batch conversion hygiene</h2>
            <p>Converting 20 contracts? Use consistent naming <code>ClientName-contract-v1.docx</code>. Log source PDF hash if legal audit trail required.</p>

            <h2>Mobile upload caveats</h2>
