            <p>Main guides: <a href="/guides/images-to-pdf">images</a> · <a href="/guides/pdf-to-word">PDF to Word</a> · <a href="/guides/split-pdf">split</a> · <a href="/compare">compare</a>.</p>
            <h2>Post-action checklist</h2>
